PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE projects (
  project_id        TEXT PRIMARY KEY,
  name              TEXT NOT NULL,
  seed_prompt       TEXT,
  description       TEXT,
  max_participants  INTEGER DEFAULT 15,
  pilot_duration_days INTEGER DEFAULT 7,
  status            TEXT DEFAULT 'active' CHECK (status IN ('active','closed','archived')),
  created_at        TEXT DEFAULT CURRENT_TIMESTAMP,
  closed_at         TEXT,
  created_by        TEXT
);
INSERT INTO "projects" ("project_id","name","seed_prompt","description","max_participants","pilot_duration_days","status","created_at","closed_at","created_by") VALUES('9f4c1edb-5dc6-45fb-a581-6fc803db4de2','Tester01','¿Cual es tu propóssito en este equipo?','Pilot',10,7,'active','2026-04-21 17:10:21',NULL,'admin');
