INSERT INTO "projects" ("project_id","name","seed_prompt","description","max_participants","pilot_duration_days","status","created_at","closed_at","created_by") VALUES('bf8ff6de-c21b-469b-ae91-ed78adf9f65c','Tes Equipo Primario CD&TIcs','Cuando piensan en su trabajo diario y en la CRA, ¿qué situaciones o sensaciones les surgen cuando intentan mostrar el valor que generamos, o cuando sienten que ese valor no logra aterrizar o ser reconocido como esperan? Cuéntennos una experiencia que ilustre esto.','Pilot',10,7,'active','2026-04-27 14:03:17',NULL,'admin');
CREATE TABLE cycles (
  cycle_id          INTEGER,
  project_id        TEXT REFERENCES projects(project_id),
  phase             TEXT CHECK (phase IN ('INVESTIGACION','ACCION','PARTICIPACION','CLOSED')),
  started_at        TEXT DEFAULT CURRENT_TIMESTAMP,
  closed_at         TEXT,
  n_participants_active INTEGER DEFAULT 0,
  n_dialogue_packets INTEGER DEFAULT 0,
  saturation_reached INTEGER DEFAULT 0, -- BOOLEAN is INTEGER in SQLite (0 or 1)
  saturation_index  REAL DEFAULT 0.0,
  consensus_reached INTEGER DEFAULT 0,
  active_agents     TEXT, -- TEXT[] in postgres, use JSON in TS
  PRIMARY KEY (project_id, cycle_id)
);
