INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('0edfd5f5-ff39-4ddd-acab-e450e7371a27','6819122158','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,4,'Gracias',replace('De nada.\n\nVolviendo a lo que mencionabas sobre ese esfuerzo de coordinación que a veces no es tan visible, ¿recuerdas alguna semana o algún día en particular donde sentiste que esa falta de reconocimiento fue especialmente frustrante o generó algún obstáculo?','\n',char(10)),'OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":2083,"token_usage":{"input_tokens":977,"output_tokens":54,"total_tokens":1199},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-29 13:21:10');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('d7fd9a1e-7963-4c91-aed7-179057635932','620110006','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,11,'De esta imagen puedes extraer temas de implementación de gobierno de datos ?',replace('Entiendo que me pides extraer temas de implementación de gobierno de datos de una imagen. Como estoy en una conversación de texto, no puedo ver imágenes.\n\nSin embargo, si quieres hablar de gobierno de datos, ¿hay alguna situación donde sintieron que fue un reto mostrar el valor de implementar un buen gobierno de datos, o que ese valor no se entendió como esperaban?','\n',char(10)),'OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":2023,"token_usage":{"input_tokens":1296,"output_tokens":77,"total_tokens":1581},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-29 17:11:08');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('9c86f930-d067-4345-8f72-ac0495f37605','6819122158','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,5,'Sí, particularmente en semanas donde se ha trabajado en iniciativas de automatización de los tableros, cuyo impacto no es tan visible porque la automatización está mejorando como hacer las cosukras que eEn este tipo de desarrollos se invierte bastante tiempo en análisis,','Entiendo. Parece que el valor de la automatización está en mejorar internamente ''cómo se hacen las cosas'', lo que es súper importante, pero no siempre es tan fácil de mostrar o de que se reconozca de inmediato como un resultado final visible.','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":4342,"token_usage":{"input_tokens":1088,"output_tokens":52,"total_tokens":1780},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-29 18:30:05');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('6f8b1a98-9539-454d-adee-d77e6c897f88','620110006','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,12,'Tener identificado el dueño del dato o definiciones de arquitectura del dato es un problema general','Entiendo que identificar al dueño del dato o tener claras las definiciones de arquitectura son problemas generales. Eso suena a que puede hacer muy difícil mostrar el valor de un','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":5267,"token_usage":{"input_tokens":1564,"output_tokens":32,"total_tokens":2360},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}','edbd3385-b489-45cb-b167-bd482eeaaab4',NULL,'2026-04-30 01:37:29');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('21122064-7364-4417-8697-a386a2522a74','620110006','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,13,'Un valor de un que?',replace('Disculpa, se cortó mi frase. Quería decir que eso suena a que puede hacer muy difícil mostrar el valor de un *buen manejo o gobierno de los datos*.\n\nPensando en eso, ¿recuerdas alguna situación específica donde la falta de un dueño claro del dato o de definiciones de arquitectura hizo que el valor de su trabajo fuera especialmente difícil de ver o de reconocer?','\n',char(10)),'OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":4051,"token_usage":{"input_tokens":1432,"output_tokens":79,"total_tokens":2179},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 01:37:59');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('28ead7ec-752c-47eb-a089-4b79b0ed2d26','620110006','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,14,'Más allá de la identificacion, es mantener claro esos lineamientos o parámetros iniciales cuando se inicia un ejercicio de ciencia de datos','Entiendo. Entonces, el reto no es solo identificar al dueño del dato o definir la arquitectura al inicio, sino mantener esos lineamientos y parámetros claros a lo largo de todo un proyecto de ciencia de datos. Eso suena a un esfuerzo constante.','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":1799,"token_usage":{"input_tokens":1461,"output_tokens":49,"total_tokens":1700},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 01:39:09');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('a2b229f7-f599-4ec7-b0ee-fc691b8b5b11','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,1,'Se identificó que es necesario actualizar algunos documentos del sistema de gestión asociados al proceso de gestión de tecnológia. El equipo ha trabajado con iniciativas de documentos nuevos, pero tal vez lo conveniente es ajustar los documentos existentes.','Entiendo, entonces están viendo si es mejor actualizar lo que ya existe en lugar de crear cosas nuevas para el sistema de gestión. ¿Recuerdas alguna','GUARDED','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":4573,"token_usage":{"input_tokens":666,"output_tokens":31,"total_tokens":1462},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:33:40');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('a48edd75-cf71-4626-ade5-b3a20fb2e309','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,2,'Por ejemplo la guía metodológica de desarrollo Scrum','Ah, la guía metodológica de desarrollo Scrum. Parece que el desafío está en cómo esos documentos, como la guía de Scrum, realmente logran comunicar el valor','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":4576,"token_usage":{"input_tokens":708,"output_tokens":32,"total_tokens":1504},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:34:39');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('9c15bb65-a46a-4f81-a922-1c616e553089','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,3,'Así es se deben incluir los lineamientos del uso de herramientas IA y de ciencia de datos.','Entiendo. Entonces, lo que mencionas suena a que la guía de Scrum necesita reflejar no solo cómo se hacen las cosas, sino también cómo las nuevas herramientas de IA y ciencia de datos están aportando valor al proceso.','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":2330,"token_usage":{"input_tokens":761,"output_tokens":46,"total_tokens":1095},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:35:42');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('384da98d-0d4d-4a98-b8f5-fd8522ad7f18','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,4,'Así es','Entiendo. Entonces, si la guía actual no incluye IA y ciencia de datos, ¿recuerdas alguna vez en la que eso haya complicado explicar el valor de lo que hacen, o que ese valor no se haya visto claramente por esa falta?','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":4038,"token_usage":{"input_tokens":811,"output_tokens":50,"total_tokens":1394},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:35:58');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('5a8b8e07-c3a3-4ece-937d-a2421e696eb0','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,5,'Lo conveniente es que el procedimiento de desarrollos de ciencia de datos este adecuadamente documentado para que otras personas lo puedan ejecutar y/o replicar. En la entidad se ha visto afectación por que el conocimiento y la información está en las personas exclusivamente y si se van no queda documentado el producto de sus actividades.','Eso tiene sentido. Lo que describes suena a que, si el conocimiento se queda solo en las personas, el valor de ese trabajo se pierde o no se puede replicar cuando alguien se va. Es como si el valor no lograra aterrizar de forma duradera.','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":2407,"token_usage":{"input_tokens":928,"output_tokens":55,"total_tokens":1177},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:39:31');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('62f14026-4d29-4261-8808-0cb6eab65bfb','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,6,'Así es estamos trabajando para que eso cambie.','Entiendo. Eso no es fácil de cargar solo.','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":1429,"token_usage":{"input_tokens":995,"output_tokens":11,"total_tokens":1053},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:40:16');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('a9d3d60f-105f-4b8f-85dd-a045ec6df3cb','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,7,'Estamos trabajando para actualizar otros documentos como la Guía de Analítica Institucional y el formato de historias de usuario.',replace('Lo que describes suena a que la actualización de esos documentos, como la Guía de Analítica o las historias de usuario, es clave para que el valor de lo que hacen quede claro y no se pierda.\n\nPor cierto, agradezco mucho tu participación constante; llevamos un avance estimado del 50% en esta fase de investigación.','\n',char(10)),'OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":2034,"token_usage":{"input_tokens":1087,"output_tokens":70,"total_tokens":1374},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:46:12');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('5c57ab71-1781-4de7-a0d8-010b1aa21597','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,8,'El reto es que los lineamientos que se definan en todos esos documentos sean de conocimiento y aplicación de todos.','Entiendo. Que esos lineamientos sean de conocimiento y aplicación de todos es un gran reto. ¿Recuerdas alguna situación concreta donde la falta de eso hizo que el valor de algún trabajo no se viera o no se aprovechara como esperaban?','OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":3562,"token_usage":{"input_tokens":1126,"output_tokens":51,"total_tokens":1715},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:47:27');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('c6782ef5-af97-4f9f-9991-e7271705836b','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,9,'Muchos éxitos en la investigacion',replace('Gracias, te lo agradezco.\n\nVolviendo a lo que decías del reto de que los lineamientos sean conocidos y aplicados por todos, ¿hay alguna situación específica que te venga a la mente donde eso hizo que el valor de un trabajo no se aprovechara como esperaban?','\n',char(10)),'OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":1871,"token_usage":{"input_tokens":1186,"output_tokens":58,"total_tokens":1431},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:47:51');
INSERT INTO "dialogue_turns" ("turn_id","participant_id","project_id","cycle_id","turn_number","user_text","val_response","emotional_register","speech_act","topics","directive_applied","latency_ms","timestamp") VALUES('de8771e0-6de9-484b-a15c-ef15cf8e3562','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c',1,10,'La falta de aplicación de lineamientos concretos ha afectado la oportunidad en la presentación y validación de los resultados.',replace('Entiendo. Que la falta de aplicación de lineamientos afecte la oportunidad en la presentación y validación de los resultados es clave.\n\nCuando piensas en eso, ¿hay alguna vez reciente en la que sintieras que un proyecto o un resultado se retrasó o no se validó a tiempo precisamente por eso?','\n',char(10)),'OPEN','REFLEXION_PASIVA','{"saberes_detectados":[],"oppressive_structures":[],"metadata":{"latency_ms":3337,"token_usage":{"input_tokens":1269,"output_tokens":64,"total_tokens":1754},"temperature":0.7,"max_tokens":800,"is_custom_prompt":false}}',NULL,NULL,'2026-04-30 21:50:08');
CREATE TABLE dialogue_states (
  participant_id    TEXT NOT NULL,
  project_id        TEXT REFERENCES projects(project_id),
  cycle_id          INTEGER DEFAULT 1,
  turn_count        INTEGER DEFAULT 0,
  emotional_register TEXT DEFAULT 'Neutral',
  momentum_score    REAL DEFAULT 0.5,
  topics_covered    TEXT, -- JSON string
  topics_pending    TEXT, -- JSON string
  active_directive_id TEXT,
  safe_harbor_active INTEGER DEFAULT 0,
  status            TEXT DEFAULT 'active' CHECK (status IN ('active','timed_out','closed','withdrawn')),
  last_turn_at      TEXT, current_phase TEXT DEFAULT 'INVESTIGACION', phase_progress REAL DEFAULT 0.0,
  PRIMARY KEY (participant_id, project_id, cycle_id)
);
