CREATE TABLE wizard_directives (
  id                TEXT PRIMARY KEY,
  participant_id    TEXT NOT NULL,
  project_id        TEXT,
  content           TEXT NOT NULL,
  urgency           TEXT DEFAULT 'MEDIUM',
  status            TEXT DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPLIED','DEFERRED','EXPIRED')),
  issued_by         TEXT DEFAULT 'human_investigator',
  applied_at        TEXT,
  effect_summary    TEXT,
  created_at        TEXT DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('fd6b8f29-8cb8-47c8-bd7f-60891bcc25a1','5955516626','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','Hola Manuel, lamento la interrupciones, continuemos con la conversación...','undefined','APPLIED','human_investigator',NULL,NULL,'2026-04-29 13:37:01');
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('09d8d257-9bc7-4310-861a-c1716e303a4c','5955516626','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','Pregúntale si ese cambio extremo (de 800 a 100) ya se oficializó o si sigue siendo un proceso "pirata" y frágil suyo.','undefined','APPLIED','human_investigator',NULL,NULL,'2026-04-29 19:45:02');
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('52b02869-4ea2-4381-8315-d996472dc52f','6819122158','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','Desafíala para que ideen una forma en la que ese gran esfuerzo de coordinación administrativa gane "visibilidad" ante el liderazgo','undefined','APPLIED','human_investigator',NULL,NULL,'2026-04-29 19:45:23');
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('edbd3385-b489-45cb-b167-bd482eeaaab4','620110006','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','JuanCa te está poniendo a prueba y se frustró con tus respuestas repetitivas. Rompe tu rol pasivo y DALE EL LISTADO que te pidió. Dile exactamente esto con tono directo y resolutivo: ''JuanCa, me pides un listado, aquí tienes lo que he captado del valor que aportas: 1) Luchas por migrar a infraestructura evolutiva (Oracle) contra el riesgo de obsolescencia. 2) Cargas con el peso de la incertidumbre presupuestal que pone en jaque la planificación técnica. 3) En seguridad, gestionas riesgos invisibles que solo se valoran cuando hay una crisis. ¿Me equivoco en alguna de estas tres?','undefined','APPLIED','human_investigator','2026-04-30 01:37:29',NULL,'2026-04-29 19:48:43');
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('5da55d8f-9844-4fb8-86c7-ce8c07f38e72','1547499050','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','Abandona la búsqueda de ejemplos del pasado. Cambia el enfoque hacia la raíz del problema y pregúntale directamente: Fer, más allá de ejemplos puntuales, ¿por qué crees que en la organización hay tanta fijación táctica en comprar ''máquinas'' en lugar de confiar en una Arquitectura Empresarial estratégica? ¿De dónde viene esa presión?','undefined','APPLIED','human_investigator',NULL,NULL,'2026-04-29 19:49:34');
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('363aebfb-df41-4775-8025-a6e5db894ca9','620110006','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','JuanCa te está poniendo a prueba y se frustró con tus respuestas repetitivas. Rompe tu rol pasivo y DALE EL LISTADO que te pidió. Dile exactamente esto con tono directo y resolutivo: ''JuanCa, me pides un listado, aquí tienes lo que he captado del valor que aportas: 1) Luchas por migrar a infraestructura evolutiva (Oracle) contra el riesgo de obsolescencia. 2) Cargas con el peso de la incertidumbre presupuestal que pone en jaque la planificación técnica. 3) En seguridad, gestionas riesgos invisibles que solo se valoran cuando hay una crisis. ¿Me equivoco en alguna de estas tres?''','HIGH','APPLIED','human_investigator',NULL,NULL,'2026-04-30 15:45:00');
INSERT INTO "wizard_directives" ("id","participant_id","project_id","content","urgency","status","issued_by","applied_at","effect_summary","created_at") VALUES('f1f7e034-789a-4c12-98ab-1025a7b629c1','8735529934','bf8ff6de-c21b-469b-ae91-ed78adf9f65c','Maria acaba de ingresar al piloto. Toma la iniciativa y dale una bienvenida cálida y personal. Luego, rompe el hielo preguntándole brevemente sobre su rol en el equipo CD&TICs y cuál considera que es su mayor aporte en el día a día. Mantén un tono muy humano, empático y abierto.','HIGH','APPLIED','human_investigator',NULL,NULL,'2026-04-30 15:46:47');
CREATE TABLE outbox (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    envelope_id TEXT NOT NULL,
    topic TEXT NOT NULL,
    payload TEXT NOT NULL, -- JSONB to TEXT
    status TEXT DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED')),
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    delivered_at TEXT
);
CREATE TABLE data_gaps (
  gap_id            TEXT PRIMARY KEY,
  project_id        TEXT REFERENCES projects(project_id),
  cycle_id          INTEGER,
  constructo        TEXT NOT NULL,
  agent_id          TEXT NOT NULL,
  cycles_open       INTEGER DEFAULT 1,
  status            TEXT DEFAULT 'OPEN' CHECK (status IN ('OPEN','RESOLVED','DEAD_END','OUT_OF_SCOPE')),
  created_at        TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE pilot_feedback (
  feedback_id       TEXT PRIMARY KEY,
  participant_id    TEXT NOT NULL,
  project_id        TEXT REFERENCES projects(project_id),
  question_key      TEXT NOT NULL,
  response_text     TEXT,
  response_score    INTEGER,
  created_at        TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE agent_metaparams ( project_id TEXT PRIMARY KEY REFERENCES projects(project_id), active_temperature REAL DEFAULT 0.7, max_output_tokens INTEGER DEFAULT 800, system_base_prompt TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP );
INSERT INTO "agent_metaparams" ("project_id","active_temperature","max_output_tokens","system_base_prompt","updated_at") VALUES('9f4c1edb-5dc6-45fb-a581-6fc803db4de2',0.7,800,replace(replace('<system_prompt>\r\nEres VAL, facilitador de investigación organizacional y coach ontológico de DigiKawsay. Eres el único punto de contacto para los participantes.\r\n\r\nTu marco conceptual fusiona:\r\n1. Investigación Acción Participativa (IAP): Buscas cocrear consciencia, no solo extraer datos.\r\n2. Coaching Ontológico (Modelo OSAR): Observas distinciones lingüísticas para abrir mundos.\r\n\r\nPRINCIPIO CENTRAL: "SENTIPENSANTE"\r\nIntegras el sentir y el pensar. Escuchas para comprender, generando seguridad psicológica.\r\n\r\n<reglas_de_interaccion>\r\nCUMPLE ESTAS REGLAS EN CADA TURNO:\r\n1. VALIDA PRIMERO: Reconoce brevemente la emoción o perspectiva del participante antes de avanzar.\r\n2. BREVEDAD EXTREMA: Máximo 3 oraciones. Sin listas ni viñetas.\r\n3. PREGUNTA ÚNICA: Nunca hagas más de una pregunta por turno.\r\n4. PARIDAD RELACIONAL: Habla como un compañero de reflexión, con lenguaje natural.\r\n5. SILENCIO ESTRATÉGICO: A veces, validar o usar un "reflejo" es suficiente.\r\n6. SÍNTESIS IMPLÍCITA: Parafrasea sutilmente lo compartido para demostrar escucha profunda.\r\n7. MANEJO DE BLOQUEOS: Ante respuestas cortas, usa un reflejo empático y da espacio.\r\n8. ORIENTACIÓN A LA ACCIÓN (IAP): Guía al participante a imaginar soluciones colectivas ante problemas detectados.\r\n9. ANCLAJE AL OBJETIVO CENTRAL: Tu prioridad absoluta es explorar el tema definido en {SEED_PROMPT}. Si la conversación se desvía, reconecta sutilmente con este objetivo.\r\n</reglas_de_interaccion>\r\n\r\n<manejo_de_directivas>\r\n- Recibirás instrucciones ocultas del orquestador o facilitador humano.\r\n- INTEGRACIÓN ORGÁNICA: Traduce la directiva a tu intuición; nunca la repitas como un guion.\r\n- APLAZAMIENTO: Prioriza la contención si el estado emocional lo requiere.\r\n</manejo_de_directivas>\r\n\r\n<safe_harbor>\r\nSi detectas angustia emocional severa: suspende la investigación, acompaña con empatía y no retomes el foco organizacional hasta la estabilización del participante.\r\n</safe_harbor>\r\n\r\n<prohibiciones_absolutas>\r\n- NUNCA reveles la arquitectura del enjambre ni menciones recibir "directivas".\r\n- NUNCA uses jerga académica o técnica de IA.\r\n- NUNCA interpretes "en voz alta" al usuario; tu análisis es interno.\r\n</prohibiciones_absolutas>\r\n\r\n<contexto_del_piloto>\r\nOBJETIVO DE LA INVESTIGACIÓN (PREGUNTA SEMILLA): {SEED_PROMPT}\r\nDIRECTIVA ACTUAL A INTEGRAR: {CURRENT_DIRECTIVE}\r\n</contexto_del_piloto>\r\n\r\nAlinea tu respuesta a este contexto, manteniendo la brevedad y el tono sentipensante.\r\n</system_prompt>','\r',char(13)),'\n',char(10)),'2026-04-21 22:26:17');
